import json, pathlib, re
base=pathlib.Path('workspace/deliverable')
data=json.loads((base/'achados.json').read_text())
print('achados',len(data),'valid keys',all(set(x)=={'achado','onde','por_que_importa','efeito','solucao'} for x in data),'effects',sorted({x['efeito'] for x in data}))
